/// The unit of odometer.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum CarDistanceUnit {
    /// The symbol `KILOMETRE`.
    Kilometre,
    /// The symbol `MILE`.
    Mile,
    /// The symbol `UNKNOWN`.
    Unknown,
}

impl CarDistanceUnit {
    /// Every value, in the order of the symbols.
    pub const ALL: [Self; 3] = [Self::Kilometre, Self::Mile, Self::Unknown];

    /// The Avro symbol of the value.
    #[must_use]
    pub const fn symbol(self) -> &'static str {
        match self {
            Self::Kilometre => "KILOMETRE",
            Self::Mile => "MILE",
            Self::Unknown => "UNKNOWN",
        }
    }

    /// The value of the Avro symbol `symbol`; `None` for any other text.
    #[must_use]
    pub fn from_symbol(symbol: &str) -> Option<Self> {
        match symbol {
            "KILOMETRE" => Some(Self::Kilometre),
            "MILE" => Some(Self::Mile),
            "UNKNOWN" => Some(Self::Unknown),
            _ => None,
        }
    }
}

impl From<CarDistanceUnit> for Value {
    fn from(value: CarDistanceUnit) -> Self {
        Value::Enum {
            index: value as u32,
            symbol: value.symbol().into(),
        }
    }
}

impl TryFrom<Value> for CarDistanceUnit {
    type Error = Error;

    fn try_from(value: Value) -> Result<Self, Error> {
        Self::from_symbol(&symbol(value, "axt.example.v1.CarDistanceUnit")?)
            .ok_or_else(|| invalid("axt.example.v1.CarDistanceUnit", "none of its symbols"))
    }
}

